-- OBADIAH - TGL Combined
-- Generated: 2026-01-22T05:20:06.765Z

-- c001-v001: pangitain ni–Obadias ganito sinabi ng–Panginoong Yahweh sa–Edom balita narinig–namin mula–kay Yahweh at–sugo sa–mga–bansa ipinadala bumangon at–tayo–ay–bumangon laban–sa–kanya sa–digmaan
-- c001-v002: narito maliit ginawa–kita sa–mga–bansa hinahamak ikaw lubha
-- c001-v003: kapalaluan ng–puso–mo nilinlang–ka naninirahan sa–mga–bitak–ng bato kataasan ng–tirahan–niya nagsasabi sa–puso–niya sino magbababa–sa–akin sa–lupa
-- c001-v004: kung itaas–mo tulad–ng–agila at–kung sa–gitna ng–mga–bituin ilagay pugad–mo mula–doon ibababa–kita sabi–ng Yahweh
-- c001-v005: kung mga–magnanakaw dumating sa–iyo kung mga–mandarambong ng–gabi paano napahamak–ka hindi–ba magnakaw–sila sapat–sa–kanila kung mga–mamimitas–ng–ubas dumating sa–iyo hindi–ba mag-iiwan–sila mga–tira
-- c001-v006: paano hinalihalita si–Esau nahukay mga–nakatago–niya
-- c001-v007: hanggang–sa hangganan itinaboy–ka lahat–ng mga–tao–ng kasunduan–mo nilinlang–ka nagwagi laban–sa–iyo mga–tao–ng kapayapaan–mo tinapay–mo maglalagay patibong sa–ilalim–mo walang pang-unawa sa–kanya
-- c001-v008: hindi–ba sa–araw na–iyon sabi–ng Yahweh at–wawasakin–ko mga–pantas mula–sa–Edom at–pang-unawa mula–sa–bundok ni–Esau
-- c001-v009: at–matatakot mga–mandirigma–mo Teman upang mahiwalay bawat–tao mula–sa–bundok ni–Esau sa–pagpatay
-- c001-v010: dahil–sa–karahasan sa–kapatid–mo Hakob tatakpan–ka ng–kahihiyan at–mahihiwalay–ka magpakailanman
-- c001-v011: sa–araw ng–pagtayo–mo sa–tapat sa–araw ng–pagkabihag ng–mga–dayuhan ng–yaman–niya at–mga–dayuhan pumasok pintuang-bayan-niya mga–pintuang-bayan–niya at–sa Herusalem nagsapalaran palabunutan maging ikaw tulad–ng–isa sa–kanila
-- c001-v012: at–huwag tumingin sa–araw–ng kapatid–mo sa–araw ng–kamalasan–niya at–huwag magsaya sa–mga–anak–ng Huda sa–araw ng–pagkawasak–nila at–huwag magmalaki bibig–mo sa–araw ng–kagipitan
-- c001-v013: huwag pumasok sa–pintuang-bayan–ng bayan–ko sa–araw ng–kapahamakan–nila huwag tumingin maging ikaw sa–kasamaan–niya sa–araw ng–kapahamakan–niya at–huwag mag-abot sa–yaman–niya sa–araw ng–kapahamakan–niya
-- c001-v014: at–huwag tumayo sa sangandaan upang–patayin ang mga–tumakas–niya at–huwag isuko mga–nakaligtas–niya sa–araw ng–kagipitan
-- c001-v015: sapagkat malapit araw–ng Yahweh sa lahat–ng mga–bansa kung–paano ginawa–mo gagawin sa–iyo gantimpala–mo babalik sa–ulo–mo
-- c001-v016: sapagkat kung–paano uminom–kayo sa bundok banal–ko iinom lahat–ng mga–bansa palagi at–iinom at–lulunok at–magiging parang–hindi naganap
-- c001-v017: at–sa–bundok Sion magkakaroon kaligtasan at–magiging banal at–aariin bahay–ni Hakob ang mga–pag-aari–nila
-- c001-v018: at–magiging bahay–ni Hakob apoy at–bahay–ni Hosep liyab at–bahay–ni Esau dayami at–susunugin sila at–lalamunin–sila at–hindi magkakaroon makakaligtas sa–bahay–ni Esau sapagkat Yahweh nagsalita
-- c001-v019: at–aariin ang–Negeb ang bundok ni–Esau at–ang–kapatagan ang mga–Filisteo at–aariin ang bukid–ng Epraim at bukid–ng Samaria at–si–Benjamin ang Gilead
-- c001-v020: at–ang–mga–bihag hukbo–ng ito ng–mga–anak–ng Israel na mga–Cananeo hanggang–sa Sarefat at–ang–mga–bihag ng–Herusalem na sa–Sepharad aariin ang mga–lungsod–ng Negeb
-- c001-v021: at–aakyat mga–tagapagligtas sa–bundok Sion upang–hatulan ang bundok ni–Esau at–magiging kay–Yahweh ang–kaharian

